import{_ as a,c as r,o as n,a0 as o}from"./chunks/framework.CAoHpFZS.js";const t="/images/SpringBoot/img/Snipaste_2025-07-02_22-12-03.png",C=JSON.parse('{"title":"Spring","description":"","frontmatter":{},"headers":[],"relativePath":"article/SpringBoot/Spring IOC容器加载过程.md","filePath":"article/SpringBoot/Spring IOC容器加载过程.md"}'),i={name:"article/SpringBoot/Spring IOC容器加载过程.md"};function c(l,e,s,p,d,g){return n(),r("div",null,e[0]||(e[0]=[o('<h1 id="spring" tabindex="-1">Spring <a class="header-anchor" href="#spring" aria-label="Permalink to &quot;Spring&quot;">​</a></h1><p><code>Spring</code>是一个轻量级的<code>Java</code>开源框架。是为了解决企业应用开发的复杂性而创建的，它使用基本的<code>JavaBean</code>来完成以前只能由<code>JEB</code>完成的事情。</p><h2 id="spring的整体架构" tabindex="-1">Spring的整体架构 <a class="header-anchor" href="#spring的整体架构" aria-label="Permalink to &quot;Spring的整体架构&quot;">​</a></h2><p>Spring框架是一个分层架构，它包含一系列的功能要素，并分为大约20个模块。 <img src="'+t+'" alt="image.png"></p><h3 id="core-container" tabindex="-1">Core Container <a class="header-anchor" href="#core-container" aria-label="Permalink to &quot;Core Container&quot;">​</a></h3><p><code>Core Container</code>核心容器：包含有：<code>Core</code>、<code>Bean</code>，<code>Context</code>和<code>Expression Language</code>模块</p><p><code>Core</code>和<code>Beans</code>模块是框架的基础部分，提供<code>IOC</code>和依赖注入特性。(BeanFactory)</p><ul><li>Core模块主要包含 Spring 框架基本的核心工具类，Spring的其他组件都会使用到这个包里的类，Core模块是其他组件的基本核心</li><li>Beans模块是所有应用都要用到的，包含访问配置文件、创建和管理bean以及进行 <code>Inversion of Control/Dependency Injection</code>操作相关的所有类</li><li>Context模块构建与Core和Bean模块基础之上，提供了一种类似于JNDI注册器的框架式的对象访问方法。Context模块集成了Beans的特性，为Spring核心提供了大量的扩展，添加了国际化（资源绑定）、事件传播、资源加载和对Context的透明创建支持。Context模块同时也支持J2EE的一些特性。ApplicationContext接口是Context模块的关键</li><li>ExpressionLanguage 模块提供了一个强大的表达式语言用于在运行时查询和操作对象。他是JSP2.1规范中定义的 <code>unifed expression language</code>的一个扩展。该语言支持设置/获取属性的值，属性的分配，方法的调用，访问数组上下文（accessiong the context of arrays）、容器和索引器、逻辑和算术运算符，命名变量以及从Spring的IOC容器中根据名称检索对象。</li></ul><h3 id="data-access-integration" tabindex="-1">Data Access/Integration <a class="header-anchor" href="#data-access-integration" aria-label="Permalink to &quot;Data Access/Integration&quot;">​</a></h3><p>Data Access/Integration层包含了有JDBC、ORM、OXM、JMS和Transaction模块</p><ul><li>JDBC：提供了一个JDBC的抽象层，消除冗长的JDBC编码和解析数据库厂商特有的错误代码。包含了Spring对JDBC数据访问进行封装的所有类</li><li>ORM：为流行的 对象-关系 映射API，如：JPA，JDO，Hibernate, Ibatis等提供了一个交互层。利用ORM封装包，可以混合使用所有Spring提供的特性进行O/R映射</li><li>OXM ：提供了一个对Object/XML映射实现的抽象层，OBJECT/XML映射实现包括JAXB，Castor，XMLBeans，JiBX和XStream</li><li>JMS（Java Message Service）：主要包含了一些制造和消费消息的特性</li><li>Transaction：支持编程和声明性的事务管理，这些事务类必须实现特定的接口，并且对所有的POJO都适用。</li></ul><h3 id="web" tabindex="-1">WEB <a class="header-anchor" href="#web" aria-label="Permalink to &quot;WEB&quot;">​</a></h3><p>Web上下文是建立在应用程序上下文模块之上的，为基于Web的应用程序提供了上下文。所以Spring框架支持与Jakarta Struts集成。Web模块简化；了处理多部分请求以及将请求参数绑定域对象的工作。Web层包含了Web、Web-Servlet、Web-Struts和Web-Porlet模块，</p><ul><li>Web：提供基础的面向Web的集成特性。如：多文件上传、使用Servlet listeners初始化IOC容器，以及一个面向Web的应用上下文。</li><li>Web-Servlet（web.servlet.jar）：包含Spring的model-view-controller(MVC)实现。</li><li>Web-Structs：提供了对Structs的支持，使得类在Spring应用中能够与一个典型的</li></ul>',14)]))}const b=a(i,[["render",c]]);export{C as __pageData,b as default};
